using System.Text.Json;
using NAudio.Wave;
namespace OpenEQ;
internal static class FormatRecoveryChecks {
 sealed class Fake(NativeFormatState state):INativeFormatBackend {public NativeFormatState Current=state;public int Writes;public Action<Fake,NativeFormatState>? OnWrite;public NativeFormatState Read()=>Current;public void Write(NativeFormatState value){Writes++;if(OnWrite!=null)OnWrite(this,value);else Current=value;}}
 static NativeFormatState Format(int rate,int bits)=>new(NativeDeviceFormat.Backend.Encode(DeviceFormats.Create(rate,bits,true)),NativeDeviceFormat.Backend.Encode(new WaveFormatExtensible(rate,32,2)));
 public static int Run(string reportPath){var cases=new List<string>();var report=new Dictionary<string,object>();void Check(bool condition,string name){if(!condition)throw new Exception(name);cases.Add(name);}void Fails(Action action){try{action();}catch{return;}throw new Exception("Expected failure was accepted");}
  string directory=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(reportPath))!,"format-recovery-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);string PathFor(string name)=>Path.Combine(directory,name+".json");
  try{var original=Format(48000,32);var next=Format(192000,24);var high=Format(384000,32);var fake=new Fake(original);string path=PathFor("roundtrip");new NativeFormatTransaction(fake,path,"test-device").Apply(next);var first=JsonSerializer.Deserialize<NativeFormatBackup>(File.ReadAllText(path))!;Check(first.Original.SameAs(original)&&fake.Current.SameAs(next),"backup_before_mutation");new NativeFormatTransaction(fake,path,"test-device").Apply(high);Check(JsonSerializer.Deserialize<NativeFormatBackup>(File.ReadAllText(path))!.Original.SameAs(original),"multiple_changes_preserve_original");new NativeFormatTransaction(fake,path,"test-device").Restore();Check(fake.Current.SameAs(original)&&!File.Exists(path)&&Directory.GetFiles(directory,"roundtrip.json.restored-*").Length==1,"restore_after_controller_restart");
   fake=new Fake(original);path=PathFor("wrong-bits");fake.OnWrite=(f,v)=>{f.Current=f.Writes==1?Format(192000,16):v;};Fails(()=>new NativeFormatTransaction(fake,path,"d").Apply(next));Check(fake.Current.SameAs(original)&&fake.Writes==2&&!File.Exists(path),"same_rate_wrong_physical_bits_rollback");
   fake=new Fake(original);path=PathFor("partial-write");fake.OnWrite=(f,v)=>{f.Current=v;if(f.Writes==1)throw new IOException("driver failed after applying format");};Fails(()=>new NativeFormatTransaction(fake,path,"d").Apply(next));Check(fake.Current.SameAs(original)&&fake.Writes==2,"partial_driver_failure_rollback");
   fake=new Fake(original);path=PathFor("rollback-fails");fake.OnWrite=(f,v)=>throw new IOException("driver unavailable");Fails(()=>new NativeFormatTransaction(fake,path,"d").Apply(next));Check(File.Exists(path)&&JsonSerializer.Deserialize<NativeFormatBackup>(File.ReadAllText(path))!.Original.SameAs(original),"rollback_failure_retains_recovery_data");
   fake=new Fake(original);path=PathFor("external-change");new NativeFormatTransaction(fake,path,"d").Apply(next);fake.Current=Format(96000,32);int writes=fake.Writes;Fails(()=>new NativeFormatTransaction(fake,path,"d").Restore());Check(fake.Writes==writes&&fake.Current.SameAs(Format(96000,32))&&File.Exists(path),"external_changes_not_overwritten");
   fake=new Fake(original);path=PathFor("missing");Fails(()=>new NativeFormatTransaction(fake,path,"d").Restore());Check(fake.Writes==0,"missing_backup_never_uses_driver_default");
   path=PathFor("corrupt");File.WriteAllText(path,"broken backup");Fails(()=>new NativeFormatTransaction(fake,path,"d").Apply(next));Check(fake.Writes==0,"corrupt_backup_blocks_mutation");
   path=PathFor("backup-blocked");Directory.CreateDirectory(path);Fails(()=>new NativeFormatTransaction(fake,path,"d").Apply(next));Check(fake.Writes==0,"backup_write_failure_blocks_mutation");
   path=PathFor("interrupted");File.WriteAllText(path,JsonSerializer.Serialize(new NativeFormatBackup("d",DateTimeOffset.UtcNow,original,next)));fake=new Fake(next);new NativeFormatTransaction(fake,path,"d").Restore();Check(fake.Current.SameAs(original),"interrupted_change_recovers_exact_original");
   fake=new Fake(original);path=PathFor("device-mismatch");File.WriteAllText(path,JsonSerializer.Serialize(new NativeFormatBackup("other-device",DateTimeOffset.UtcNow,original,next)));Fails(()=>new NativeFormatTransaction(fake,path,"d").Apply(next));Check(fake.Writes==0,"different_device_backup_rejected");
   fake=new Fake(original);path=PathFor("failed-restore");new NativeFormatTransaction(fake,path,"d").Apply(next);fake.OnWrite=(f,v)=>{f.Current=v;if(f.Writes==2)throw new IOException("restore failed after changing device");};Fails(()=>new NativeFormatTransaction(fake,path,"d").Restore());Check(fake.Current.SameAs(next)&&File.Exists(path),"partial_restore_failure_rolls_back_and_keeps_backup");fake.OnWrite=null;new NativeFormatTransaction(fake,path,"d").Restore();Check(fake.Current.SameAs(original),"failed_restore_can_be_retried");
   fake=new Fake(original);var malformed=Format(48000,24);malformed.Endpoint[12]=1;Fails(()=>new NativeFormatTransaction(fake,PathFor("malformed"),"d").Apply(malformed));Check(fake.Writes==0,"invalid_block_alignment_rejected_before_mutation");
   Check(AudioRestartGuard.NeedsRestart(new("device",0x100,0))&&AudioRestartGuard.NeedsRestart(new("device",0,14))&&!AudioRestartGuard.NeedsRestart(new("device",0,0)),"pending_restart_flags_detected");
   string telemetryPath=Path.Combine(directory,"telemetry.bin");using(var writer=new FileStream(telemetryPath,FileMode.Create,FileAccess.ReadWrite,FileShare.ReadWrite)){writer.SetLength(4096);writer.Position=1456;writer.Write(BitConverter.GetBytes(1.25));writer.Flush();using var reader=new NativeTelemetryReader(telemetryPath);Check(reader.InputEnergy==1.25,"telemetry_opens_while_controller_has_write_access");writer.Position=1472;writer.Write(BitConverter.GetBytes(.5));writer.Flush();Check(reader.OutputEnergy==.5,"telemetry_observes_controller_updates_without_exclusive_file_lock");}
   report["result"]="PASS";return 0;
  }catch(Exception e){report["result"]="FAIL";report["exception"]=e.ToString();return 1;}finally{report["cases"]=cases;report["count"]=cases.Count;report["scope"]="Fault injection using an in-memory driver; no live audio format, device binding or policy changes";File.WriteAllText(reportPath,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));}
 }
 public static int Health(string reportPath){var report=new Dictionary<string,object>();try{report["endpoints"]=AudioEngine.Devices().Where(d=>d.Transport!="虚拟").Select(d=>{var f=NativeDeviceFormat.Read(d.Id);var nodes=AudioRestartGuard.Read(d.Id);return new{device=d,physical_format=NativeFormatState.Describe(f.Endpoint),mix_format=NativeFormatState.Describe(f.Mix),driver_nodes=nodes,needs_restart=nodes.Any(AudioRestartGuard.NeedsRestart),active_playback=AudioActivityGuard.Active(d.Id),native_apo_bound=NativeApo.Installed(d.Id)};}).ToArray();report["unsigned_audio_enabled"]=NativeApo.UnsignedAllowed();report["result"]="PASS";return 0;}catch(Exception e){report["result"]="FAIL";report["exception"]=e.ToString();return 1;}finally{report["scope"]="Read-only device and driver inspection; no playback, format changes, installation or policy changes";File.WriteAllText(reportPath,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true,Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}));}}
}

